from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_date, points)
        self._credits: dict[str, list[tuple[date, int]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")

        points = int(amount // 10)
        if points > 0:
            available_on = day + timedelta(days=14)
            self._credits.setdefault(customer, []).append((available_on, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        credits = self._credits.get(customer, [])
        return sum(points for available_on, points in credits if available_on <= day)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points < 0:
            raise ValueError("Cannot redeem negative points")
        if points > self.balance(customer, day):
            raise ValueError("Insufficient points")

        if points == 0:
            return

        credits = self._credits.get(customer, [])
        # Only points already available can be spent; consume oldest-first (FIFO)
        remaining = points
        for i, (available_on, credit_points) in enumerate(credits):
            if remaining == 0:
                break
            if available_on > day:
                continue
            if credit_points <= remaining:
                remaining -= credit_points
                credits[i] = (available_on, 0)
            else:
                credits[i] = (available_on, credit_points - remaining)
                remaining = 0
